def cmd_project_list(conn, args):
    # 只读查询：名称按保存原值返回（含重名、中文、引号与内部空白），
    # 按项目标识数值升序；没有项目时返回 []
    try:
        rows = conn.execute(
            "SELECT id, name FROM projects ORDER BY id ASC"
        ).fetchall()
    except sqlite3.Error as exc:
        storage_error(str(exc))
    emit([{"id": row[0], "name": row[1]} for row in rows])

